/**
 * pdf-master.js — Sanalys PDF Template Engine v3.1
 * ─────────────────────────────────────────────────
 * v3.1: pill con esquinas rectas, datos de clínica desde admin,
 *       margen inferior para evitar overlap con footer,
 *       columnas de tabla con anchos corregidos.
 */
(function () {
    'use strict';

    /* ══════════════════════════════════════
       TOKENS DE DISEÑO
    ══════════════════════════════════════ */
    const T = {
        VERDE:      [10,  61,  51],
        VERDE_MID:  [14,  80,  66],
        FLUO:       [208, 255, 78],
        NEGRO:      [18,  18,  18],
        GRIS_OSC:   [70,  70,  70],
        GRIS:       [130, 130, 130],
        GRIS_CLARO: [210, 210, 210],
        GRIS_FONDO: [249, 250, 251],
        BLANCO:     [255, 255, 255],
        ROJO:       [210, 40,  40],
        VERDE_OK:   [22,  163, 74],
        AMARILLO:   [202, 138, 4],
        FONT:       'helvetica',
        M:          14,
        HEADER_H:   36,
        START_Y:    44,
        START_Y_L:  44,
        FOOTER_Y_P: 275,
        FOOTER_Y_L: 188,
    };

    /* Logo embebido */
    const LOGO_DATA_URL = 'data:image/png;base64,';

    /* ══════════════════════════════════════
       DATOS DE LA CLÍNICA
       Se sobrescriben con SanalysPDF.setClinica(data)
       cuando el módulo carga su config de Firestore/admin.
    ══════════════════════════════════════ */
    /* Defaults: deben coincidir con lo que está configurado en admin → config/datosClinica.
       Si setClinica() se llama correctamente, estos valores se sobreescriben con los del admin. */
    let _clinica = {
        nombre:    'Sanalys',
        direccion: '25 de mayo 1845, Santa Fe',
        telefono:  '3424597639',
        email:     'sanalys.sf@gmail.com',
        instagram: '@sanalys.sf',
        web:       'sanalys.com.ar',
        facebook:  '',
        tiktok:    '',
        slogan:    '',
    };

    /* ══════════════════════════════════════
       HEADER
    ══════════════════════════════════════ */
    function _drawHeader(doc, opts) {
        const W = doc.internal.pageSize.getWidth();
        const { titulo = '', subtitulo = '', emisor = '' } = opts;

        doc.setFillColor(...T.BLANCO);
        doc.rect(0, 0, W, T.HEADER_H + 10, 'F');

        /* FILA 1 — Logo + Slogan */
        const ROW1_Y = 13;
        const LOGO_W = 46;
        const LOGO_H = LOGO_W / (600 / 149);
        try {
            doc.addImage(LOGO_DATA_URL, 'PNG', T.M, ROW1_Y - LOGO_H + 2, LOGO_W, LOGO_H);
        } catch(e) {
            doc.setFont(T.FONT, 'bold'); doc.setFontSize(15);
            doc.setTextColor(...T.VERDE); doc.text('sanalys', T.M, ROW1_Y);
        }

        /* Slogan: "La ciencia de " + [estar bien.] con rectángulo SIN curvas */
        const PILL_FS   = 7.5;
        const PAD_H     = 1.5;   /* [FIX] era 2.8 → espacio excesivo antes de "estar bien." */
        const PAD_V     = 1.4;

        doc.setFont(T.FONT, 'bold');
        doc.setFontSize(PILL_FS);
        const pillTW = doc.getTextWidth('estar bien.');
        const pillW  = pillTW + PAD_H * 2;
        const pillH  = PILL_FS * 0.353 + PAD_V * 2;

        doc.setFont(T.FONT, 'normal');
        doc.setFontSize(PILL_FS);
        const prefixTW = doc.getTextWidth('La ciencia de ');

        const sloganTotal = prefixTW + pillW;
        const sloganX     = W - T.M - sloganTotal;
        const baselineY   = ROW1_Y;
        const pillTop     = baselineY - pillH + PAD_V + 0.5;

        /* Texto prefijo */
        doc.setFont(T.FONT, 'normal'); doc.setFontSize(PILL_FS);
        doc.setTextColor(...T.VERDE);
        doc.text('La ciencia de ', sloganX, baselineY);

        /* Rectángulo fluo — esquinas RECTAS, como en el manual de marca */
        doc.setFillColor(...T.FLUO);
        doc.rect(sloganX + prefixTW, pillTop, pillW, pillH, 'F');   /* ← rect, NO roundedRect */

        /* Texto "estar bien." — negrita */
        doc.setFont(T.FONT, 'bold');
        doc.setFontSize(PILL_FS);
        doc.setTextColor(...T.VERDE);
        doc.text('estar bien.', sloganX + prefixTW + PAD_H, baselineY - 0.3);

        /* SEPARADOR 1 */
        const SEP1_Y = ROW1_Y + 4;
        doc.setDrawColor(...T.VERDE); doc.setLineWidth(0.4);
        doc.line(T.M, SEP1_Y, W - T.M, SEP1_Y);

        /* FILA 2 — Título + metadata */
        const ROW2_Y = SEP1_Y + 9;

        doc.setFont(T.FONT, 'bold');
        doc.setFontSize(titulo.length > 40 ? 8.5 : 10.5);
        doc.setTextColor(...T.NEGRO);
        doc.text(titulo.toUpperCase(), T.M, ROW2_Y);

        const fecha = new Date().toLocaleDateString('es-AR');
        const hora  = new Date().toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit' });

        if (subtitulo) {
            doc.setFont(T.FONT, 'normal'); doc.setFontSize(7);
            doc.setTextColor(...T.GRIS_OSC);
            doc.text(subtitulo, W - T.M, ROW2_Y - 3, { align: 'right' });
        }
        doc.setFont(T.FONT, 'normal'); doc.setFontSize(6.5);
        doc.setTextColor(...T.GRIS);
        const metaParts = [emisor ? 'Emitido por ' + emisor : null, fecha + ' · ' + hora].filter(Boolean);
        doc.text(metaParts.join('  ·  '), W - T.M, subtitulo ? ROW2_Y + 3.5 : ROW2_Y, { align: 'right' });

        /* SEPARADOR 2 */
        doc.setDrawColor(...T.VERDE); doc.setLineWidth(0.4);
        doc.line(T.M, T.HEADER_H, W - T.M, T.HEADER_H);
    }

    function _drawFooter(doc, opts) {
        const W     = doc.internal.pageSize.getWidth();
        const isL   = W > 220;
        const fY    = isL ? T.FOOTER_Y_L : T.FOOTER_Y_P;
        const total = doc.internal.getNumberOfPages();

        const nombre2  = opts.nombre    || _clinica.nombre;
        const dir      = opts.direccion || _clinica.direccion;
        const tel      = opts.telefono  || _clinica.telefono;
        const email    = opts.email     || _clinica.email;
        const ig       = opts.instagram || _clinica.instagram;
        const web      = opts.web       || _clinica.web;
        const fb       = _clinica.facebook || '';
        const tt       = _clinica.tiktok   || '';

        // Línea derecha: ig · web [· fb] [· tt] — solo los que tengan valor
        const socialParts = [ig, web, fb, tt].filter(Boolean);
        const socialLine  = socialParts.join('  ·  ');

        for (let p = 1; p <= total; p++) {
            doc.setPage(p);

            doc.setDrawColor(...T.VERDE); doc.setLineWidth(0.4);
            doc.line(T.M, fY, W - T.M, fY);

            const COL2_X = W * 0.52;

            /* Col izquierda — nombre + dirección + contacto */
            doc.setFont(T.FONT, 'bold'); doc.setFontSize(6);
            doc.setTextColor(...T.NEGRO);
            doc.text(nombre2 + '  ·  ' + dir, T.M, fY + 5);

            doc.setFont(T.FONT, 'normal'); doc.setFontSize(6);
            doc.setTextColor(...T.GRIS);
            doc.text(tel + '  ·  ' + email, T.M, fY + 9.5);

            /* Separador vertical */
            doc.setDrawColor(...T.GRIS_CLARO); doc.setLineWidth(0.25);
            doc.line(COL2_X - 4, fY + 3, COL2_X - 4, fY + 13);

            /* Col derecha — redes + paginación */
            if (socialLine) {
                doc.setFont(T.FONT, 'normal'); doc.setFontSize(6);
                doc.setTextColor(...T.VERDE);
                doc.text(socialLine, W - T.M, fY + 5.5, { align: 'right', maxWidth: COL2_X - T.M - 8 });
            }

            doc.setFont(T.FONT, 'normal'); doc.setFontSize(6);
            doc.setTextColor(...T.GRIS);
            doc.text('Pag. ' + p + ' / ' + total, W - T.M, fY + 10.5, { align: 'right' });
        }
    }

    /* ══════════════════════════════════════
       API PÚBLICA
    ══════════════════════════════════════ */
    const SanalysPDF = {

        T,

        /**
         * Cargar datos reales de la clínica desde Firestore (admin).
         * Llamar con: SanalysPDF.setClinica(datosClinica)
         * donde datosClinica es el objeto del doc config/datosClinica.
         */
        setClinica(data) {
            if (!data) return;
            if (data.nombre)    _clinica.nombre    = data.nombre;
            if (data.direccion) _clinica.direccion = data.direccion;
            if (data.telefono)  _clinica.telefono  = data.telefono;
            if (data.email)     _clinica.email     = data.email;
            if (data.instagram) _clinica.instagram = data.instagram;
            if (data.web)       _clinica.web       = data.web;
            if (data.facebook)  _clinica.facebook  = data.facebook;
            if (data.tiktok)    _clinica.tiktok    = data.tiktok;
            if (data.slogan)    _clinica.slogan    = data.slogan;
            console.log('[SanalysPDF] Clinica configurada:', _clinica.nombre);
        },

        crear(opts = {}) {
            if (!window.jspdf) throw new Error('[SanalysPDF] jsPDF no disponible.');
            const { jsPDF } = window.jspdf;
            const doc = new jsPDF(opts.orient || 'p', 'mm', 'a4');
            _drawHeader(doc, opts);
            return { doc, startY: T.START_Y };
        },

        footer(doc, opts = {}) {
            _drawFooter(doc, opts);
        },

        /**
         * Config base para autoTable.
         * IMPORTANTE: margin.bottom reserva espacio para el footer
         * y evita que la tabla superponga el pie de página.
         */
        tableConfig(overrides = {}) {
            const { _didParseCell, _didDrawCell, ...rest } = overrides;
            return {
                styles: {
                    fontSize:    8,
                    textColor:   T.NEGRO,
                    cellPadding: { top: 3.5, right: 5, bottom: 3.5, left: 5 },
                    lineWidth:   0,
                    font:        T.FONT,
                    overflow:    'linebreak',
                },
                headStyles: {
                    fillColor:   T.VERDE,
                    textColor:   T.BLANCO,
                    fontStyle:   'bold',
                    fontSize:    7,
                    cellPadding: { top: 4, right: 5, bottom: 4, left: 5 },
                    lineWidth:   0,
                },
                alternateRowStyles: { fillColor: T.GRIS_FONDO },
                theme: 'plain',
                /* margen inferior = espacio reservado para el footer de página */
                margin: { left: T.M, right: T.M, bottom: 24 },
                didDrawCell(data) {
                    if (data.section === 'body') {
                        data.doc.setDrawColor(...T.GRIS_CLARO);
                        data.doc.setLineWidth(0.15);
                        data.doc.line(
                            data.cell.x, data.cell.y + data.cell.height,
                            data.cell.x + data.cell.width, data.cell.y + data.cell.height
                        );
                    }
                    if (_didDrawCell) _didDrawCell(data);
                },
                didParseCell: _didParseCell || undefined,
                ...rest,
            };
        },

        sectionTitle(doc, text, y, color) {
            const W = doc.internal.pageSize.getWidth();
            doc.setFillColor(...T.FLUO);
            doc.rect(T.M, y - 3.5, 2, 5.5, 'F');
            doc.setFont(T.FONT, 'bold'); doc.setFontSize(8.5);
            doc.setTextColor(...(color || T.NEGRO));
            doc.text(text.toUpperCase(), T.M + 4, y + 0.5);
            const textW = doc.getTextWidth(text.toUpperCase());
            doc.setDrawColor(...T.GRIS_CLARO); doc.setLineWidth(0.2);
            doc.line(T.M + 5.5 + textW, y, W - T.M, y);
            return y + 9;
        },

        kpiBox(doc, x, y, w, h, label, valor, color) {
            doc.setFillColor(247, 248, 249);
            doc.setDrawColor(...T.GRIS_CLARO); doc.setLineWidth(0.3);
            doc.roundedRect(x, y, w, h, 1.5, 1.5, 'FD');
            doc.setFillColor(...T.FLUO);
            doc.rect(x + 2, y, w - 4, 0.9, 'F');
            doc.setFont(T.FONT, 'normal'); doc.setFontSize(5.5);
            doc.setTextColor(...T.GRIS);
            doc.text(label.toUpperCase(), x + w / 2, y + 6, { align: 'center' });
            doc.setFont(T.FONT, 'bold'); doc.setFontSize(10);
            doc.setTextColor(...(color || T.NEGRO));
            doc.text(String(valor), x + w / 2, y + h - 3.5, { align: 'center' });
            return x + w + 3;
        },

        save(doc, filename, footerOpts = {}) {
            this.footer(doc, footerOpts);
            console.log('[SanalysPDF] Guardando:', filename);
            doc.save(filename);
        },
    };

    window.SanalysPDF = SanalysPDF;
    console.log('[SanalysPDF] v3.1 listo.');

})();
